export function getProductsByCategory(category: string): Product[] {
  return products.filter(p => p.category === category);
}

export function getProductBySlug(slug: string): Product | undefined {
  return products.find(p => p.slug === slug);
}

export function getFeaturedProducts(n = 8): Product[] {
  return products.filter(p => p.inStock).slice(0, n);
}

export function getTopSelling(n = 4): Product[] {
  return products.filter(p => p.inStock && p.discount && p.discount > 10).slice(0, n);
}

export interface Category {
  slug: string;
  name: string;
  description: string;
  image: string;
}

